import 'package:flutter/foundation.dart';
import '../../../data/repositories/recipe_extraction_repository.dart';
import '../../../data/services/recipe_extraction_service.dart';
import '../../../domain/models/recipe.dart';
import '../../../utils/logger.dart';
import '../../../data/repositories/recipe_repository.dart';

enum RecipeExtractionStatus { idle, loading, success, error }

class RecipeExtractionViewModel extends ChangeNotifier {
  final RecipeExtractionRepository _repo;
  RecipeExtractionViewModel({RecipeExtractionRepository? repository})
      : _repo = repository ?? RecipeExtractionRepository(const RecipeExtractionService());

  String url = '';
  RecipeExtractionStatus status = RecipeExtractionStatus.idle;
  Recipe? recipe;
  String? errorMessage;
  bool _saving = false;
  bool get isSaving => _saving;

  bool get canExtract => url.trim().isNotEmpty && status != RecipeExtractionStatus.loading;
  bool get canSave => status == RecipeExtractionStatus.success && recipe != null && !_saving;

  Future<void> extract() async {
    final target = url.trim();
    if (target.isEmpty) return;
    status = RecipeExtractionStatus.loading;
    errorMessage = null;
    recipe = null;
    notifyListeners();
    try {
      final r = await _repo.extract(target);
      recipe = r;
      status = RecipeExtractionStatus.success;
    } catch (e, st) {
      Logger.e('Extraction failed', e, st);
      errorMessage = e.toString();
      status = RecipeExtractionStatus.error;
    }
    notifyListeners();
  }

  Future<bool> saveCurrent() async {
    if (!canSave) return false;
    _saving = true;
    notifyListeners();
    try {
      await recipeRepository.upsert(recipe!);
      return true;
    } catch (e, st) {
      Logger.e('Save recipe failed', e, st);
      return false;
    } finally {
      _saving = false;
      notifyListeners();
    }
  }

  void setUrl(String value) {
    url = value;
    notifyListeners();
  }

  void reset() {
    url = '';
    recipe = null;
    errorMessage = null;
    status = RecipeExtractionStatus.idle;
    notifyListeners();
  }
}

import 'package:flutter/foundation.dart';
import '../../../data/repositories/recipe_extraction_repository.dart';
import '../../../data/services/recipe_extraction_service.dart';
import '../../../domain/models/recipe.dart';
import '../../../utils/logger.dart';
import '../../../data/repositories/recipe_repository.dart';

enum RecipeExtractionStatus { idle, loading, success, error }

class RecipeExtractionViewModel extends ChangeNotifier {
  final RecipeExtractionRepository _repo;
  RecipeExtractionViewModel({RecipeExtractionRepository? repository})
      : _repo = repository ?? RecipeExtractionRepository(const RecipeExtractionService());

  String url = '';
  RecipeExtractionStatus status = RecipeExtractionStatus.idle;
  Recipe? recipe;
  String? errorMessage;
  bool _saving = false;
  bool get isSaving => _saving;

  bool get canExtract => url.trim().isNotEmpty && status != RecipeExtractionStatus.loading;
  bool get canSave => status == RecipeExtractionStatus.success && recipe != null && !_saving;

  Future<void> extract() async {
    final target = url.trim();
    if (target.isEmpty) return;
    status = RecipeExtractionStatus.loading;
    errorMessage = null;
    recipe = null;
    notifyListeners();
    try {
      final r = await _repo.extract(target);
      recipe = r;
      status = RecipeExtractionStatus.success;
    } catch (e, st) {
      Logger.e('Extraction failed', e, st);
      errorMessage = e.toString();
      status = RecipeExtractionStatus.error;
    }
    notifyListeners();
  }

  Future<bool> saveCurrent() async {
    if (!canSave) return false;
    _saving = true;
    notifyListeners();
    try {
      await recipeRepository.upsert(recipe!);
      return true;
    } catch (e, st) {
      Logger.e('Save recipe failed', e, st);
      return false;
    } finally {
      _saving = false;
      notifyListeners();
    }
  }

  void setUrl(String value) {
    url = value;
    notifyListeners();
  }

  void reset() {
    url = '';
    recipe = null;
    errorMessage = null;
    status = RecipeExtractionStatus.idle;
    notifyListeners();
  }

  // ---------- Editing API ----------
  void updateTitle(String value) {
    final r = recipe; if (r == null) return; r.title = value; notifyListeners();
  }

  void updateDescription(String value) {
    final r = recipe; if (r == null) return; r.description = value; notifyListeners();
  }

  void updateServings(String value) {
    final r = recipe; if (r == null) return; r.servings = value; notifyListeners();
  }

  void updateImageUrl(String value) {
    final r = recipe; if (r == null) return; r.imageUrl = value.isEmpty ? null : value; notifyListeners();
  }

  void addIngredient([String value = '']) {
    final r = recipe; if (r == null) return; r.ingredients.add(value); notifyListeners();
  }

  void updateIngredient(int index, String value) {
    final r = recipe; if (r == null) return; if (index < 0 || index >= r.ingredients.length) return; r.ingredients[index] = value; notifyListeners();
  }

  void removeIngredient(int index) {
    final r = recipe; if (r == null) return; if (index < 0 || index >= r.ingredients.length) return; r.ingredients.removeAt(index); notifyListeners();
  }

  void addStep([String value = '']) {
    final r = recipe; if (r == null) return; r.steps.add(value); notifyListeners();
  }

  void updateStep(int index, String value) {
    final r = recipe; if (r == null) return; if (index < 0 || index >= r.steps.length) return; r.steps[index] = value; notifyListeners();
  }

  void removeStep(int index) {
    final r = recipe; if (r == null) return; if (index < 0 || index >= r.steps.length) return; r.steps.removeAt(index); notifyListeners();
  }
}

import 'package:flutter/material.dart';
import '../../recipe_extraction/view_model/recipe_extraction_view_model.dart';

class RecipeExtractionScreen extends StatefulWidget {
  const RecipeExtractionScreen({super.key});

  @override
  State<RecipeExtractionScreen> createState() => _RecipeExtractionScreenState();
}

class _RecipeExtractionScreenState extends State<RecipeExtractionScreen> {
  late final RecipeExtractionViewModel _vm;
  final _controller = TextEditingController();

  @override
  void initState() {
    super.initState();
    _vm = RecipeExtractionViewModel();
    _vm.addListener(_onChanged);
  }

  void _onChanged() => setState(() {});

  @override
  void dispose() {
    _vm.removeListener(_onChanged);
    _controller.dispose();
    super.dispose();
  }

  Future<void> _extract() async => _vm.extract();

  Future<void> _save() async {
    final ok = await _vm.saveCurrent();
    if (!mounted) return;
    if (ok) {
      final id = _vm.recipe!.id;
      // Navigate to detail page
      Navigator.of(context).pushNamed('/recipe', arguments: id);
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Rezept gespeichert.')));
    } else {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Speichern fehlgeschlagen')));
    }
  }

  Widget _buildResult() {
    switch (_vm.status) {
      case RecipeExtractionStatus.idle:
        return const Text('Bitte eine Rezept-URL eingeben.');
      case RecipeExtractionStatus.loading:
        return const Center(child: CircularProgressIndicator());
      case RecipeExtractionStatus.error:
        return Text('Fehler: ${_vm.errorMessage}', style: const TextStyle(color: Colors.red));
      case RecipeExtractionStatus.success:
        final r = _vm.recipe!;
        return SingleChildScrollView(
          key: const ValueKey('result'),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              if (r.imageUrl != null)
                Padding(
                  padding: const EdgeInsets.only(bottom: 12),
                  child: ClipRRect(
                    borderRadius: BorderRadius.circular(8),
                    child: Image.network(r.imageUrl!, height: 180, width: double.infinity, fit: BoxFit.cover, errorBuilder: (_, __, ___) => const SizedBox()),
                  ),
                ),
              Text(r.title, style: Theme.of(context).textTheme.headlineSmall),
              if (r.servings != null)
                Padding(
                  padding: const EdgeInsets.only(top: 4),
                  child: Row(
                    children: [
                      const Icon(Icons.person_2, size: 14, color: Colors.grey),
                      const SizedBox(width: 4),
                      Text(r.servings!, style: const TextStyle(fontStyle: FontStyle.italic, fontSize: 13, color: Colors.grey)),
                    ],
                  ),
                ),
              if (r.description != null && r.description!.isNotEmpty)
                Padding(
                  padding: const EdgeInsets.only(top: 8, bottom: 16),
                  child: Text(r.description!),
                ),
              if (r.ingredients.isNotEmpty) ...[
                const Text('Zutaten', style: TextStyle(fontWeight: FontWeight.bold)),
                const SizedBox(height: 4),
                ...r.ingredients.map((i) => Text('\u2022 $i')),
                const SizedBox(height: 16),
              ],
              if (r.steps.isNotEmpty) ...[
                const Text('Schritte', style: TextStyle(fontWeight: FontWeight.bold)),
                const SizedBox(height: 4),
                ...r.steps.asMap().entries.map((e) => Padding(
                      padding: const EdgeInsets.only(bottom: 4),
                      child: Text('${e.key + 1}. ${e.value}'),
                    )),
              ],
              const SizedBox(height: 16),
              if (r.totalTime != null) Text('Gesamtzeit: ${r.totalTime!.inMinutes} Minuten'),
              if (r.sourceUrl != null) Text('Quelle: ${r.sourceUrl}', style: const TextStyle(fontSize: 12, color: Colors.grey)),
            ],
          ),
        );
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('Rezept Extraktion')),
      floatingActionButton: _vm.canSave
          ? FloatingActionButton.extended(
              onPressed: _vm.isSaving ? null : _save,
              icon: _vm.isSaving ? const SizedBox(height: 16, width: 16, child: CircularProgressIndicator(strokeWidth: 2)) : const Icon(Icons.save),
              label: const Text('Speichern'),
            )
          : null,
      body: Padding(
        padding: const EdgeInsets.all(16),
        child: Column(
          children: [
            TextField(
              controller: _controller,
              decoration: const InputDecoration(
                labelText: 'Rezept URL',
                border: OutlineInputBorder(),
              ),
              onChanged: _vm.setUrl,
            ),
            const SizedBox(height: 12),
            Row(
              children: [
                ElevatedButton.icon(
                  onPressed: _vm.canExtract ? _extract : null,
                  icon: const Icon(Icons.download),
                  label: const Text('Extrahieren'),
                ),
                const SizedBox(width: 12),
                TextButton(onPressed: _vm.status == RecipeExtractionStatus.loading ? null : _vm.reset, child: const Text('Zurücksetzen')),
              ],
            ),
            const SizedBox(height: 16),
            Expanded(child: AnimatedSwitcher(duration: const Duration(milliseconds: 250), child: _buildResult())),
          ],
        ),
      ),
    );
  }
}

import 'package:flutter/material.dart';
import '../../recipe_extraction/view_model/recipe_extraction_view_model.dart';

class RecipeExtractionScreen extends StatefulWidget {
  const RecipeExtractionScreen({super.key});

  @override
  State<RecipeExtractionScreen> createState() => _RecipeExtractionScreenState();
}

class _RecipeExtractionScreenState extends State<RecipeExtractionScreen> {
  late final RecipeExtractionViewModel _vm;
  final _controller = TextEditingController();

  @override
  void initState() {
    super.initState();
    _vm = RecipeExtractionViewModel();
    _vm.addListener(_onChanged);
  }

  void _onChanged() => setState(() {});

  @override
  void dispose() {
    _vm.removeListener(_onChanged);
    _controller.dispose();
    super.dispose();
  }

  Future<void> _extract() async => _vm.extract();

  Future<void> _save() async {
    final ok = await _vm.saveCurrent();
    if (!mounted) return;
    if (ok) {
      final id = _vm.recipe!.id;
      // Navigate to detail page
      Navigator.of(context).pushNamed('/recipe', arguments: id);
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Rezept gespeichert.')));
    } else {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Speichern fehlgeschlagen')));
    }
  }

  Widget _buildEditableList({
    required String title,
    required List<String> items,
    required void Function() onAdd,
    required void Function(int) onRemove,
    required void Function(int, String) onChange,
    String hintText = '',
  }) {
    return Card(
      margin: const EdgeInsets.only(top: 12),
      child: Padding(
        padding: const EdgeInsets.all(12),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Row(
              mainAxisAlignment: MainAxisAlignment.spaceBetween,
              children: [
                Text(title, style: const TextStyle(fontWeight: FontWeight.bold)),
                TextButton.icon(onPressed: onAdd, icon: const Icon(Icons.add), label: const Text('Hinzufügen')),
              ],
            ),
            const SizedBox(height: 6),
            if (items.isEmpty)
              Text('Noch keine Einträge. Tippe auf "Hinzufügen".', style: TextStyle(color: Colors.grey[600]))
            else
              ...items.asMap().entries.map((e) {
                final idx = e.key;
                final val = e.value;
                return Padding(
                  padding: const EdgeInsets.only(bottom: 8),
                  child: Row(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Expanded(
                        child: TextFormField(
                          key: ValueKey('$title-$idx-${_vm.recipe?.id}'),
                          initialValue: val,
                          onChanged: (v) => onChange(idx, v),
                          maxLines: null,
                          decoration: InputDecoration(
                            isDense: true,
                            hintText: hintText.isNotEmpty ? hintText : '$title $idx',
                            border: const OutlineInputBorder(),
                            contentPadding: const EdgeInsets.symmetric(vertical: 10, horizontal: 12),
                          ),
                        ),
                      ),
                      const SizedBox(width: 8),
                      IconButton(
                        tooltip: 'Entfernen',
                        onPressed: () => onRemove(idx),
                        icon: const Icon(Icons.delete_outline),
                      ),
                    ],
                  ),
                );
              }),
          ],
        ),
      ),
    );
  }

  Widget _buildResult() {
    switch (_vm.status) {
      case RecipeExtractionStatus.idle:
        return const Text('Bitte eine Rezept-URL eingeben.');
      case RecipeExtractionStatus.loading:
        return const Center(child: CircularProgressIndicator());
      case RecipeExtractionStatus.error:
        return Text('Fehler: ${_vm.errorMessage}', style: const TextStyle(color: Colors.red));
      case RecipeExtractionStatus.success:
        final r = _vm.recipe!;
        return SingleChildScrollView(
          key: ValueKey('result-${r.id}'),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              if (r.imageUrl != null && r.imageUrl!.isNotEmpty)
                Padding(
                  padding: const EdgeInsets.only(bottom: 12),
                  child: ClipRRect(
                    borderRadius: BorderRadius.circular(8),
                    child: Image.network(r.imageUrl!, height: 180, width: double.infinity, fit: BoxFit.cover, errorBuilder: (_, __, ___) => const SizedBox()),
                  ),
                ),
              Card(
                child: Padding(
                  padding: const EdgeInsets.all(12),
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      TextFormField(
                        key: ValueKey('title-${r.id}'),
                        initialValue: r.title,
                        onChanged: _vm.updateTitle,
                        decoration: const InputDecoration(labelText: 'Titel', border: OutlineInputBorder()),
                      ),
                      const SizedBox(height: 8),
                      Row(
                        children: [
                          Expanded(
                            child: TextFormField(
                              key: ValueKey('servings-${r.id}'),
                              initialValue: r.servings ?? '',
                              onChanged: _vm.updateServings,
                              decoration: const InputDecoration(labelText: 'Portionen / Menge', border: OutlineInputBorder()),
                            ),
                          ),
                          const SizedBox(width: 8),
                          Expanded(
                            child: TextFormField(
                              key: ValueKey('image-${r.id}'),
                              initialValue: r.imageUrl ?? '',
                              onChanged: _vm.updateImageUrl,
                              decoration: const InputDecoration(labelText: 'Bild-URL', border: OutlineInputBorder()),
                            ),
                          ),
                        ],
                      ),
                      const SizedBox(height: 8),
                      TextFormField(
                        key: ValueKey('desc-${r.id}'),
                        initialValue: r.description ?? '',
                        onChanged: _vm.updateDescription,
                        maxLines: null,
                        decoration: const InputDecoration(labelText: 'Beschreibung', border: OutlineInputBorder()),
                      ),
                    ],
                  ),
                ),
              ),
              _buildEditableList(
                title: 'Zutaten',
                items: r.ingredients,
                onAdd: _vm.addIngredient,
                onRemove: _vm.removeIngredient,
                onChange: _vm.updateIngredient,
                hintText: 'z. B. 200 g Mehl',
              ),
              _buildEditableList(
                title: 'Schritte',
                items: r.steps,
                onAdd: _vm.addStep,
                onRemove: _vm.removeStep,
                onChange: _vm.updateStep,
                hintText: 'z. B. Backofen vorheizen …',
              ),
              const SizedBox(height: 8),
              if (r.totalTime != null) Text('Gesamtzeit: ${r.totalTime!.inMinutes} Minuten'),
              if (r.sourceUrl != null) Text('Quelle: ${r.sourceUrl}', style: const TextStyle(fontSize: 12, color: Colors.grey)),
              const SizedBox(height: 80),
            ],
          ),
        );
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('Rezept Extraktion')),
      floatingActionButton: _vm.canSave
          ? FloatingActionButton.extended(
              onPressed: _vm.isSaving ? null : _save,
              icon: _vm.isSaving ? const SizedBox(height: 16, width: 16, child: CircularProgressIndicator(strokeWidth: 2)) : const Icon(Icons.save),
              label: const Text('Speichern'),
            )
          : null,
      body: Padding(
        padding: const EdgeInsets.all(16),
        child: Column(
          children: [
            TextField(
              controller: _controller,
              decoration: const InputDecoration(
                labelText: 'Rezept URL',
                border: OutlineInputBorder(),
              ),
              onChanged: _vm.setUrl,
            ),
            const SizedBox(height: 12),
            Row(
              children: [
                ElevatedButton.icon(
                  onPressed: _vm.canExtract ? _extract : null,
                  icon: const Icon(Icons.download),
                  label: const Text('Extrahieren'),
                ),
                const SizedBox(width: 12),
                TextButton(onPressed: _vm.status == RecipeExtractionStatus.loading ? null : _vm.reset, child: const Text('Zurücksetzen')),
              ],
            ),
            const SizedBox(height: 16),
            Expanded(child: AnimatedSwitcher(duration: const Duration(milliseconds: 250), child: _buildResult())),
          ],
        ),
      ),
    );
  }
}

import 'package:flutter_test/flutter_test.dart';
import 'package:rezept/data/services/recipe_extraction_service.dart';

void main() {
  test('flattens HowToSection/HowToStep into plain text steps', () {
    const html = '''<html><head>
      <script type="application/ld+json">{
        "@context": "https://schema.org",
        "@type": "Recipe",
        "name": "Test Fajitas",
        "recipeIngredient": ["1 onion", "2 peppers", "300 g mushrooms"],
        "recipeInstructions": [{
          "@type": "HowToSection",
          "name": "Hinweis: Foo",
          "itemListElement": [
            {"@type": "HowToStep", "name": "Preheat oven.", "text": "Preheat the oven to 200 C."},
            {"@type": "HowToStep", "text": "Slice the peppers and onions."},
            {"@type": "HowToStep", "text": "Bake for 30 minutes."}
          ]
        }]
      }</script>
    </head><body></body></html>''';

    final recipe = const RecipeExtractionService().parseHtml(html);
    expect(recipe.title, contains('Fajitas'));
    expect(recipe.steps.isNotEmpty, isTrue);
    expect(recipe.steps.first.toLowerCase(), contains('preheat'));
    expect(recipe.steps.any((s) => s.toLowerCase().contains('slice the peppers')), isTrue);
  });
}
